sc_cat_item_producer.script:
(function executeProducer() {

    // =========================================================
    // 1. GET LOGGED-IN EMPLOYEE
    // =========================================================
    var employeeId = gs.getUserID();

    if (!employeeId) {
        gs.addErrorMessage('Unable to identify the logged-in employee.');
        current.setAbortAction(true);
        return;
    }


    // =========================================================
    // 2. GET SELECTED ATTENDANCE RECORD
    // =========================================================
    var attendanceId = String(producer.attendance_record || '');

    if (!attendanceId) {
        gs.addErrorMessage('Please select an attendance record.');
        current.setAbortAction(true);
        return;
    }

    var attendance = new GlideRecord(
        'x_1760545_smarta_0_attendance'
    );

    if (!attendance.get(attendanceId)) {
        gs.addErrorMessage(
            'Selected attendance record was not found.'
        );
        current.setAbortAction(true);
        return;
    }


    // =========================================================
    // 3. SECURITY CHECK
    // Employee can request correction only for own attendance
    // =========================================================
    if (
        attendance.getValue('employee') !== employeeId
    ) {
        gs.addErrorMessage(
            'You can only request corrections for your own attendance.'
        );
        current.setAbortAction(true);
        return;
    }


    // =========================================================
    // 4. FIND ACTIVE EMPLOYEE PROFILE
    // =========================================================
    var profile = new GlideRecord(
        'x_1760545_smarta_0_employee_profile'
    );

    profile.addQuery('employee', employeeId);
    profile.addQuery('active', true);
    profile.setLimit(1);
    profile.query();

    if (!profile.next()) {
        gs.addErrorMessage(
            'Active SmartAttend employee profile was not found.'
        );
        current.setAbortAction(true);
        return;
    }


    // =========================================================
    // 5. GET EMPLOYEE MANAGER
    // =========================================================
    var managerId = profile.getValue('manager');

    if (!managerId) {
        gs.addErrorMessage(
            'Manager is not configured in your SmartAttend employee profile.'
        );
        current.setAbortAction(true);
        return;
    }


    // =========================================================
    // 6. GET PRODUCER VALUES
    // =========================================================
    var requestedStatus =
        String(producer.requested_status || '');

    var requestedCheckIn =
        String(producer.requested_check_in || '');

    var requestedCheckOut =
        String(producer.requested_check_out || '');

    var reason =
        String(producer.reason || '');


    // =========================================================
    // 7. VALIDATE REQUIRED VALUES
    // =========================================================
    if (!requestedStatus) {
        gs.addErrorMessage(
            'Please select the requested attendance status.'
        );
        current.setAbortAction(true);
        return;
    }

    if (!reason) {
        gs.addErrorMessage(
            'Please enter a reason for the correction.'
        );
        current.setAbortAction(true);
        return;
    }


    // =========================================================
    // 8. POPULATE ATTENDANCE CORRECTION REQUEST
    // =========================================================

    current.setValue(
        'employee',
        employeeId
    );

    current.setValue(
        'attendance',
        attendance.getUniqueValue()
    );

    current.setValue(
        'attendance_date',
        attendance.getValue('attendance_date')
    );

    current.setValue(
        'current_status',
        attendance.getValue('status')
    );

    current.setValue(
        'requested_status',
        requestedStatus
    );


    // Only set optional fields when employee entered a value
    if (requestedCheckIn) {
        current.setValue(
            'requested_check_in',
            requestedCheckIn
        );
    }

    if (requestedCheckOut) {
        current.setValue(
            'requested_check_out',
            requestedCheckOut
        );
    }


    current.setValue(
        'reason',
        reason
    );

    current.setValue(
        'manager',
        managerId
    );

    current.setValue(
        'state',
        'submitted'
    );


    // Optional success message
    gs.addInfoMessage(
        'Attendance correction request submitted successfully.'
    );

})();
